from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_perimeter_pos(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            elif x == 0:
                return 3 * side + (side - y)
            return 0  # Should not happen as points are on boundary

        # Convert points to their perimeter positions
        pos = [(get_perimeter_pos(x, y), x, y) for x, y in points]
        pos.sort()

        def can_select(d):
            count = 0
            last_pos = -1
            for p, x, y in pos:
                if last_pos == -1 or p - last_pos >= d:
                    count += 1
                    last_pos = p
                    if count == k:
                        return True
            return False

        low = 0
        high = 2 * side
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if mid == 0:
                ans = max(ans, mid)
                low = mid + 1
                continue
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

import sys

# Increase recursion depth just in case, though iterative DSU is used
sys.setrecursionlimit(300000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
    except StopIteration:
        return

    # Read grid F
    F = []
    for _ in range(H):
        row = []
        for _ in range(W):
            row.append(int(next(iterator)))
        F.append(row)

    # Read Q
    try:
        Q = int(next(iterator))
    except StopIteration:
        Q = 0

    queries = []
    for i in range(Q):
        A = int(next(iterator)) - 1
        B = int(next(iterator)) - 1
        Y = int(next(iterator))
        C = int(next(iterator)) - 1
        D = int(next(iterator)) - 1
        Z = int(next(iterator))
        queries.append((A, B, Y, C, D, Z))

    def get_id(r, c):
        return r * W + c

    total_blocks = H * W
    parent = list(range(total_blocks))

    # Iterative find with path compression
    def find(i):
        path = []
        while i != parent[i]:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    # Prepare blocks sorted by height descending
    blocks = []
    for r in range(H):
        for c in range(W):
            blocks.append((F[r][c], r, c))

    blocks.sort(key=lambda x: x[0], reverse=True)

    # component_queries[root] stores list of (query_index, other_block_index)
    component_queries = [[] for _ in range(total_blocks)]

    # queries_at[block] stores list of (query_index, other_block_index) for queries involving this block
    queries_at = [[] for _ in range(total_blocks)]
    for idx, (A, B, Y, C, D, Z) in enumerate(queries):
        start_id = get_id(A, B)
        end_id = get_id(C, D)
        queries_at[start_id].append((idx, end_id))
        queries_at[end_id].append((idx, start_id))

    ans = [None] * Q

    # Process blocks from highest to lowest height
    for h, r, c in blocks:
        u = get_id(r, c)
        # Activate u (parent[u] is already u)

        # Add queries to the component of u
        for q_idx, other in queries_at[u]:
            if ans[q_idx] is None:
                root_u = find(u)
                component_queries[root_u].append((q_idx, other))

        # Check neighbors and union if they are already active
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                v = get_id(nr, nc)
                # Only union if v is already activated (parent[v] == v)
                if parent[v] == v:
                    root_u = find(u)
                    root_v = find(v)
                    if root_u != root_v:
                        # Merge smaller list into larger list for efficiency
                        if len(component_queries[root_u]) < len(component_queries[root_v]):
                            root_u, root_v = root_v, root_u

                        # Check queries in root_v that connect to root_u
                        for q_idx, other in component_queries[root_v]:
                            if ans[q_idx] is None:
                                if find(other) == root_u:
                                    ans[q_idx] = h
                        # Check queries in root_u that connect to root_v
                        for q_idx, other in component_queries[root_u]:
                            if ans[q_idx] is None:
                                if find(other) == root_v:
                                    ans[q_idx] = h

                        # Merge lists
                        for q_idx, other in component_queries[root_v]:
                            component_queries[root_u].append((q_idx, other))
                        component_queries[root_v] = []
                        parent[root_v] = root_u

    final_results = []
    for i, (A, B, Y, C, D, Z) in enumerate(queries):
        if A == C and B == D:
            # Start and end are the same building
            final_results.append(abs(Y - Z))
        else:
            k_max = ans[i]
            if k_max is None:
                # Should not happen as all blocks are connected at height 1
                k_max = 1
            # Calculate minimum stairs
            # If Z <= k_max, we can reach Z directly from Y (going down to Z)
            # Cost: Y - Z
            # If Z > k_max, we go down to k_max, cross, then go up to Z
            # Cost: (Y - k_max) + (Z - k_max) = Y + Z - 2 * k_max
            if Z <= k_max:
                final_results.append(Y - Z)
            else:
                final_results.append(Y + Z - 2 * k_max)

    for res in final_results:
        print(res)

if __name__ == '__main__':
    solve()

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7

        def modInverse(a, m):
            return pow(a, m - 2, m)

        def nCr_mod(n, r, mod):
            if r < 0 or r > n:
                return 0
            num = 1
            den = 1
            for i in range(r):
                num = (num * (n - i)) % mod
                den = (den * (i + 1)) % mod
            return (num * modInverse(den, mod)) % mod

        N = m * n
        if k < 2:
            return 0

        # Sum of distances between all pairs in a line of length L
        def line_sum(L):
            if L <= 1:
                return 0
            return L * (L * L - 1) // 6

        # Total sum of Manhattan distances over all pairs of cells
        # Horizontal component: each row contributes line_sum(n), and there are m rows
        # Vertical component: each column contributes line_sum(m), and there are n columns
        total_manhattan = (m * line_sum(n) + n * line_sum(m)) % MOD

        # Number of ways to choose k cells such that two specific cells are included
        # This is C(N-2, k-2)
        ways = nCr_mod(N - 2, k - 2, MOD)

        return (total_manhattan * ways) % MOD

import sys

# Increase recursion depth just in case, though not using recursion here.
sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Use dictionaries to store lb and ub for rows that have constraints
    # lb[r] = max c such that (r, c) is Black
    # ub[r] = min (c-1) such that (r, c) is White
    lb = {}
    ub = {}

    for _ in range(M):
        try:
            r = int(next(iterator))
            c = int(next(iterator))
            type_char = next(iterator)

            if type_char == 'B':
                if r not in lb or c > lb[r]:
                    lb[r] = c
            else: # 'W'
                val = c - 1
                if r not in ub or val < ub[r]:
                    ub[r] = val
        except StopIteration:
            break

    # Collect critical rows
    # Critical rows are those with non-default lb/ub, plus boundaries 1 and N
    critical_rows = set()
    critical_rows.add(1)
    critical_rows.add(N)

    for r in lb:
        critical_rows.add(r)
    for r in ub:
        critical_rows.add(r)

    sorted_rows = sorted(list(critical_rows))

    # Compute P[r] = max_{k >= r} LB[k]
    # We only need P values at sorted_rows
    P = {}
    current_max = 0
    # Iterate backwards
    for r in reversed(sorted_rows):
        val = lb.get(r, 0)
        if val > current_max:
            current_max = val
        P[r] = current_max

    # Compute Q[r] = min_{k <= r} UB[k]
    Q = {}
    current_min = N
    # Iterate forwards
    for r in sorted_rows:
        val = ub.get(r, N)
        if val < current_min:
            current_min = val
        Q[r] = current_min

    # Check conditions
    possible = True

    # Condition 1: P[r] <= Q[r] for all r in critical_rows
    for r in sorted_rows:
        if P[r] > Q[r]:
            possible = False
            break

    if possible:
        # Condition 2: P[x_{j+1}] <= Q[x_j] for all adjacent pairs in critical_rows
        # This ensures P[r] <= Q[r] for all r in intervals (x_j, x_{j+1}]
        for i in range(len(sorted_rows) - 1):
            r_curr = sorted_rows[i]
            r_next = sorted_rows[i+1]
            if P[r_next] > Q[r_curr]:
                possible = False
                break

    if possible:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def check(k):
            flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                length = j - i
                if length > k:
                    flips += (length - 1) // k
                i = j
            return flips <= numOps

        left, right = 1, n
        ans = n
        while left <= right:
            mid = (left + right) // 2
            if check(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1
        return ans
